# typed: strict
# frozen_string_literal: true

# Generated by scripts/formula.ts in tab0inc/happen for each release; edits here are overwritten.
class Happen < Formula
  desc "Message space between you and a supervising Claude Code session"
  homepage "https://github.com/tab0inc/happen-releases"
  license :cannot_represent

  depends_on :macos

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.9.0/happen_0.9.0_darwin_arm64.tar.gz"
      sha256 "6285125195921d391fa98b14a5f1e68b6afdab96c63feda9ac69fe2b1ce82959"
    else
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.9.0/happen_0.9.0_darwin_amd64.tar.gz"
      sha256 "d7dcaccedd83bc3884d7b5f11a52af5c5a503b28c6de4bf643ba4f18b47e35b5"
    end
  end

  def install
    bin.install "happen"
  end

  def caveats
    <<~EOS
      Set up this Mac, start the server (it also starts at login), and connect a browser:
        happen open
      Start a chief: tell Claude Code to run happen skill --space <space>
      and follow it, or type in the session:
        ! happen skill --space <space>
    EOS
  end

  service do
    run [opt_bin/"happen", "serve"]
    keep_alive true
    log_path var/"log/happen.log"
    error_log_path var/"log/happen.log"
    environment_variables PATH: std_service_path_env
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/happen version")
  end
end
